1	// Keeps config/model-mapping.json in sync with provider pricing and Artificial Analysis
2	// data. Entries whose aaSlug still exists in AA data are never touched, so manual choices
3	// and notes survive; missing, null, or broken entries are (re)matched by model name.
4	
5	import { readFile, writeFile } from "node:fs/promises";
6	import path from "node:path";
7	import {
8	  baseModelName,
9	  loadCandidates,
10	  type AaModel,
11	  type MappingEntry,
12	  type Provider,
13	} from "../scoring/compute-scores.ts";
14	
15	const MAPPING_FILE = path.join("config", "model-mapping.json");
16	
17	// Order-insensitive token key, so "Claude Haiku 4.5" matches AA's "Claude 4.5 Haiku (Reasoning)".
18	function nameKey(name: string): string {
19	  return baseModelName(name)
20	    .toLowerCase()
21	    .split(/[^a-z0-9]+/)
22	    .filter(Boolean)
23	    .sort()
24	    .join(" ");
25	}
26	
27	// Maps name key -> slug of AA's base variant (the unsuffixed slug, e.g. "gpt-5-6-luna" rather
28	// than "gpt-5-6-luna-low"), or null when the variants can't be told apart.
29	function buildAaIndex(models: AaModel[]): Map<string, string | null> {
30	  const groups = new Map<string, string[]>();
31	  for (const model of models) {
32	    const key = nameKey(model.name);
33	    groups.set(key, [...(groups.get(key) ?? []), model.slug]);
34	  }
35	
36	  const index = new Map<string, string | null>();
37	  for (const [key, slugs] of groups) {
38	    const shortest = slugs.reduce((a, b) => (b.length < a.length ? b : a));
39	    const isBase = slugs.every((s) => s === shortest || s.startsWith(`${shortest}-`));
40	    index.set(key, isBase ? shortest : null);
41	  }
42	  return index;
43	}
44	
45	// Mirrors the hand-written layout: one entry per line, blank line between providers.
46	function serialize(mapping: MappingEntry[]): string {
47	  const groups = new Map<Provider, MappingEntry[]>();
48	  for (const entry of mapping) {
49	    groups.set(entry.provider, [...(groups.get(entry.provider) ?? []), entry]);
50	  }
51	  const formatEntry = (entry: MappingEntry) =>
52	    `  { ${Object.entries(entry)
53	      .map(([k, v]) => `${JSON.stringify(k)}: ${JSON.stringify(v)}`)
54	      .join(", ")} }`;
55	  const blocks = [...groups.values()].map((group) => group.map(formatEntry).join(",\n"));
56	  return `[\n${blocks.join(",\n\n")}\n]\n`;
57	}
58	
59	export async function updateModelMapping(): Promise<void> {
60	  const candidates = await loadCandidates();
61	  const aaData = JSON.parse(
62	    await readFile(path.join("data", "artificial-analysis", "language-models.json"), "utf8"),
63	  );
64	  const aaModels = aaData.models as AaModel[];
65	  const aaSlugs = new Set(aaModels.map((m) => m.slug));
66	  const aaIndex = buildAaIndex(aaModels);
67	  const mapping: MappingEntry[] = JSON.parse(await readFile(MAPPING_FILE, "utf8"));
68	
69	  const changes: string[] = [];
70	  let unmatched = 0;
71	
72	  for (const candidate of candidates) {
73	    const label = `${candidate.provider}/${candidate.model}`;
74	    const entry = mapping.find(
75	      (m) => m.provider === candidate.provider && m.providerModel === candidate.model,
76	    );
77	    if (entry?.aaSlug && aaSlugs.has(entry.aaSlug)) continue;
78	
79	    // undefined: no AA model with this name; null: several variants, none clearly the base.
80	    const match = aaIndex.get(nameKey(candidate.model));
81	
82	    if (match) {
83	      if (entry) {
84	        changes.push(`updated ${label}: ${entry.aaSlug ?? "null"} -> ${match}`);
85	        entry.aaSlug = match;
86	        delete entry.note;
87	      } else {
88	        mapping.push({
89	          provider: candidate.provider,
90	          providerModel: candidate.model,
91	          aaSlug: match,
92	        });
93	        changes.push(`added ${label} -> ${match}`);
94	      }
95	      continue;
96	    }
97	
98	    unmatched++;
99	    if (!entry) {
100	      const note =
101	        match === null
102	          ? "Auto: several Artificial Analysis variants match this name; set aaSlug by hand."
103	          : "Auto: no Artificial Analysis match found; set aaSlug by hand if one exists.";
104	      mapping.push({
105	        provider: candidate.provider,
106	        providerModel: candidate.model,
107	        aaSlug: null,
108	        note,
109	      });
110	      changes.push(`added ${label} -> null`);
111	    } else if (entry.aaSlug) {
112	      changes.push(`updated ${label}: ${entry.aaSlug} (no longer in AA data) -> null`);
113	      entry.note = `Auto: previous aaSlug "${entry.aaSlug}" no longer exists in Artificial Analysis data.`;
114	      entry.aaSlug = null;
115	    }
116	    // Existing null entries with no new match are left as-is, keeping their note.
117	  }
118	
119	  for (const change of changes) console.log(`  ${change}`);
120	  if (changes.length === 0) {
121	    console.log(`Model mapping up to date (${unmatched} candidates without an AA match).`);
122	    return;
123	  }
124	
125	  await writeFile(MAPPING_FILE, serialize(mapping));
126	  console.log(
127	    `Wrote ${changes.length} mapping changes to ${MAPPING_FILE} (${unmatched} candidates without an AA match).`,
128	  );
129	}
