// parser throw on non-numeric Input/Output prices. Run from the repo root.
import { pathToFileURL } from "node:url";

// Same guard the pipeline sets, so any pipeline the agent starts refuses to repair.
process.env.PARSER_REPAIR_SESSION = "1";

const repo = "C:/Code/onion-sellers";
const { createAgentSession, ModelRuntime, SessionManager } = await import(
  pathToFileURL(`${repo}/node_modules/@earendil-works/pi-coding-agent/dist/index.js`).href
);

const provider = process.env.PI_REPAIR_PROVIDER;
const modelId = process.env.PI_REPAIR_MODEL;
const modelRuntime = await ModelRuntime.create();
const model = modelRuntime.getModel(provider, modelId);
if (!model) throw new Error(`Pi has no model ${provider}/${modelId}`);

const { session } = await createAgentSession({
  cwd: repo,
  model,
  modelRuntime,
  tools: ["read", "grep", "find", "ls", "edit", "write", "powershell"],
  sessionManager: SessionManager.inMemory(),
});

session.subscribe((event) => {
  if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") {
    process.stdout.write(event.assistantMessageEvent.delta);
  } else if (event.type === "tool_execution_start") {
    console.log(`\n[pi] -> ${event.toolName} ${JSON.stringify(event.args).slice(0, 200)}`);
  }
});

