  "Verify:",
  "1. The parser still returns the same 16 rows for data/clinepass/source.html.",
  '2. It throws when one Input price in that HTML is replaced with "n/a". Do this in memory; do not modify data/clinepass/source.html.',
  "3. Run `npm run lint` and `npm run format` and fix anything they report.",
  "",
  "Do not run `npm start` or any other part of the pipeline. Finish with a short summary of the change.",
].join("\n");

try {
  await session.prompt(prompt);
} finally {
  session.dispose();
}

